## Usage

Import the correctly scoped store from `#/storage`. Each instance of `Storage`
(the base class, not to be used directly), has the following interface:

- `set([...scope, key], value)`
- `get([...scope, key])`
- `remove([...scope, key])`
- `removeMany([...scope], [...keys])`

For example, using our `device` store looks like this, since it's scoped to the
device (the most base level scope):

```typescript
import { device } from '#/storage';

device.set(['foobar'], true);
device.get(['foobar']);
device.remove(['foobar']);
device.removeMany([], ['foobar']);
```

## Scoped Stores

Some stores are (or might be) scoped to an account or other identifier. In this
case, storage instances are created with type-guards, like this:

```typescript
type AccountSchema = {
  language: `${string}-${string}`;
};

type DID = `did:${string}`;

const account = new Storage<
  [DID],
  AccountSchema
>({
  id: 'account',
});

account.set(
  ['did:plc:abc', 'language'],
  'en-US',
);

const language = account.get([
  'did:plc:abc',
  'language',
]);
```

Here, if `['did:plc:abc']` is not supplied along with the key of
`language`, the `get` will return undefined (and TS will yell at you).

### Basic Example

```tsx
import {BottomSheet, BottomSheetProvider, BottomSheetOutlet} from '@modules/bottom-sheet'

// In your app root:
function App() {
  return (
    <BottomSheetProvider>
      <YourApp />
      <BottomSheetOutlet />
    </BottomSheetProvider>
  )
}

// In a component:
function MyComponent() {
  const sheetRef = useRef<BottomSheet>(null)

  const openSheet = () => {
    sheetRef.current?.present()
  }

  const closeSheet = () => {
    sheetRef.current?.dismiss()
  }

  return (
    <>
      <Button onPress={openSheet} title="Open Sheet" />

      <BottomSheet
        ref={sheetRef}
        cornerRadius={16}
        backgroundColor="white"
        onStateChange={(e) => console.log(e.nativeEvent.state)}
      >
        <View style={{padding: 20}}>
          <Text>Sheet content</Text>
          <Button onPress={closeSheet} title="Close" />
        </View>
      </BottomSheet>
    </>
  )
}
```

### React Context API

The module provides a React Context provider for managing preferences in the app:

```typescript
import {
  BackgroundNotificationPreferencesProvider,
  useBackgroundNotificationPreferences,
} from 'expo-background-notification-handler/src/BackgroundNotificationHandlerProvider'

function App() {
  return (
    <BackgroundNotificationPreferencesProvider>
      <YourApp />
    </BackgroundNotificationPreferencesProvider>
  )
}

function SettingsScreen() {
  const {preferences, setPref} = useBackgroundNotificationPreferences()

  return (
    <Toggle
      value={preferences.playSoundChat}
      onValueChange={(value) => setPref('playSoundChat', value)}
    />
  )
}
```

## Usage Example

```typescript
import {
  PlatformInfo,
  AudioCategory,
  Referrer,
  SharedPrefs,
  VisibilityView
} from 'expo-bluesky-swiss-army'

// Check for reduced motion
const isReducedMotion = PlatformInfo.getIsReducedMotionEnabled()

// Set audio category for video playback (iOS)
PlatformInfo.setAudioCategory(AudioCategory.Playback)
PlatformInfo.setAudioActive(true)

// Check how user arrived at the app
const referrer = Referrer.getReferrerInfo()
if (referrer) {
  console.log('User came from:', referrer.hostname)
}

// Store a preference
SharedPrefs.setValue('lastOpenedAt', Date.now())
SharedPrefs.setValue('hasSeenOnboarding', true)

// Track visible view
<VisibilityView
  enabled={true}
  onChangeStatus={(isActive) => {
    if (isActive) {
      // This view is now the primary visible view
      video.play()
    } else {
      video.pause()
    }
  }}
>
  <VideoPlayer />
</VisibilityView>
```

## Translating text

```tsx
const langPrefs = useLanguagePrefs()
const {translate} = useTranslate({key: post.uri})

// ...

void translate({
  text: record.text,
  targetLangCode: langPrefs.primaryLanguage,
})
```

## Clearing/hiding a translation

```tsx
const {clearTranslation} = useTranslate({key: post.uri})

// ...

clearTranslation()
```

## Rendering a translation

```tsx
const {translationState} = useTranslate({key: post.uri})

// ...

switch (translationState.status) {
  case 'idle':
    // Default state; render a link that calls `translate`.
    break;
  case 'loading':
    // On-device translation is in progress; render a loading spinner.
    break;
  case 'success':
    // Translation complete; render `translationState.translatedText` and a link
    // that calls `clearTranslation`.
    break;
  case 'error':
    // On-device translation failed; render `translationState.message` and a
    // link to `translate` from `useGoogleTranslate` as a fallback.
    break;
}
```
